derivation_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Class of ICI" = 'PD-1' AND "Monotherapy/combination" = 'Monotherapy' AND "Cancer type" = 'Bladder'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_schedule(source_value) AS "schedule"
FROM base;
